const fs=require('fs'),cp=require('child_process'),crypto=require('crypto'),assert=require('assert/strict');
for(const [p,sha] of [['AGENTS.md','3827d3f35b226f98aa3115d4a976ed596be822b4'],['workspaces/codespace-mcp-srs-design/AGENTS.md','56978792276e65f53ca60fa1a91a30b13898cc18']])assert.equal(cp.execFileSync('git',['hash-object',p],{encoding:'utf8'}).trim(),sha,'Applicable instructions changed; reread required');
const d='workspaces/codespace-mcp-srs-design/expression-inventory/remaining-210/';
const source=fs.readFileSync(d+'rewrites.json');const records=JSON.parse(source);assert.equal(records.length,210);
const pairs=records.map(x=>{assert.equal(typeof x.source,'string');assert(x.canonical);return {original_function_definition:x.source,canonical_forms:x.canonical};});
const bytes=Buffer.from(JSON.stringify(pairs,null,2)+'\n');fs.writeFileSync(d+'original-canonical-pairs.json',bytes);
const reread=JSON.parse(fs.readFileSync(d+'original-canonical-pairs.json'));assert.equal(reread.length,records.length);for(let i=0;i<records.length;i++){assert.deepEqual(Object.keys(reread[i]),['original_function_definition','canonical_forms']);assert.equal(reread[i].original_function_definition,records[i].source);assert.deepEqual(reread[i].canonical_forms,records[i].canonical);}
const manifest=JSON.parse(fs.readFileSync(d+'manifest.json'));manifest.files=manifest.files.filter(x=>x.name!=='original-canonical-pairs.json');manifest.files.push({name:'original-canonical-pairs.json',bytes:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),projection_of:'rewrites.json',source_sha256:crypto.createHash('sha256').update(source).digest('hex')});manifest.files.sort((a,b)=>a.name.localeCompare(b.name));fs.writeFileSync(d+'manifest.json',JSON.stringify(manifest,null,2)+'\n');console.log(JSON.stringify({pairs:pairs.length,fields:Object.keys(pairs[0]),source_and_forms_preserved:true,bytes:bytes.length,semantic_status:'existing_partial_forms_unchanged'}));
